/**
 * Reading and validating a creature's relief rig, `variants/<id>/<dir>/relief.json`.
 *
 * The file is generated by `scripts/relief/build_relief.py` from a per-creature config, so in
 * practice it is well-formed; the checks here exist so that a hand edit or a half-converted
 * creature fails with a message that names the field, and the pet falls back to the older rig
 * renderer instead of drawing something broken.
 */

import type { Vec2 } from './math';
import type { BoneDef, Jiggle } from './skeleton';

export class ReliefDefinitionError extends Error {}

export type Rect = [number, number, number, number];

export type WeightRule =
  | { kind: 'rigid'; bone: string }
  | { kind: 'chain'; points: Vec2[]; bones: string[]; base: string; baseLen: number }
  | { kind: 'ear'; base: Vec2; tip: Vec2; parent: string; bones: [string, string] }
  | {
      kind: 'spine';
      bones: string[];
      ys: number[];
      legs: { bone: string; x: number; halfWidth: Vec2; y: Vec2 }[];
    }
  | {
      kind: 'head';
      bone: string;
      neck: { bone: string; weight: number; y: Vec2 };
      cheeks?: { left: string; right: string; centerX: number; dx: Vec2; y: Vec2 };
    };

export interface ReliefPart {
  name: string;
  /** Where the part's pixels sit in the atlas, `[x, y, w, h]` in atlas px. */
  atlas: Rect;
  /** Where the part sits in the key art, `[x, y, w, h]` in art px (same w/h as in the atlas). */
  rect: Rect;
  /** Height of the relief map's white, in art px. */
  relief: number;
  /** Depth of the part's base plane, art px towards the viewer. */
  z: number;
  /** Mesh cell size in art px. */
  cell: number;
  weights: WeightRule;
  /** Glue the part onto another part's surface (the jaw rides on the muzzle). */
  surface?: string;
}

export interface ReliefEye {
  name: string;
  atlas: Rect;
  /** The same eye with the ball painted over by the cutter: the lid skin. */
  closedAtlas: Rect;
  rect: Rect;
  /** Ball ellipse (centre and radii) in the eye's own 0..1 uv. */
  ellipse: { c: Vec2; r: Vec2 };
  bone: string;
  surface: string;
}

/** Which bones do what, so one brain can animate creatures with different anatomy. */
export interface ReliefRoles {
  ears: { left: string[]; right: string[] };
  wings: { left: string; right: string } | null;
  tails: string[][];
  legs: string[];
}

export interface ReliefDefinition {
  version: 1;
  id: string;
  atlas: string;
  depth: string;
  artSize: number;
  /** Ground contact point of the creature in art px. */
  ground: Vec2;
  /** Art px from the ground to the ear tips. */
  artHeight: number;
  bones: BoneDef[];
  parts: ReliefPart[];
  eyes: ReliefEye[];
  /** Back-to-front draw order of part names; `#eyes` marks where the eyes are drawn. */
  order: string[];
  headBones: string[];
  neck: { bone: string; headness: number };
  headCenter: [number, number, number];
  bodyCenter: [number, number, number];
  /** Point on the face the look-at logic aims from. */
  lookAnchor: Vec2;
  light: [number, number, number];
  focal: number;
  /** Largest head yaw / head pitch / body yaw in radians at full deflection. */
  turn: { yaw: number; pitch: number; body: number };
  roles: ReliefRoles;
  /** Per key pose (from `rig.json` poses): scale about the ground so it matches the relief art. */
  poses: Record<string, { scale: number }>;
}

/** Highest spring damping the fixed physics sub-step integrates stably (see `parseJiggle`). */
export const MAX_DAMPING = 300;

const SAFE_FILE = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
const NAME = /^[a-z#][a-z0-9_.-]*$/;
const REQUIRED_BONES = ['root', 'hips', 'spine', 'chest', 'neck', 'head', 'jaw'] as const;

function fail(where: string, what: string): never {
  throw new ReliefDefinitionError(`${where}: ${what}`);
}

function obj(v: unknown, where: string): Record<string, unknown> {
  if (typeof v !== 'object' || v === null || Array.isArray(v)) fail(where, 'must be a JSON object');
  return v as Record<string, unknown>;
}

function num(v: unknown, where: string, min = -1e6, max = 1e6): number {
  if (typeof v !== 'number' || !Number.isFinite(v)) fail(where, 'must be a number');
  if (v < min || v > max) fail(where, `must be between ${min} and ${max}, got ${v}`);
  return v;
}

function str(v: unknown, where: string, re: RegExp = NAME): string {
  if (typeof v !== 'string' || !re.test(v) || v.includes('..')) fail(where, 'must be a plain name');
  return v;
}

function arr(v: unknown, where: string): unknown[] {
  if (!Array.isArray(v)) fail(where, 'must be an array');
  return v;
}

function nums<N extends number>(v: unknown, n: N, where: string): number[] {
  const a = arr(v, where);
  if (a.length !== n) fail(where, `must have ${n} numbers`);
  return a.map((x, i) => num(x, `${where}[${i}]`));
}

const vec2 = (v: unknown, where: string): Vec2 => nums(v, 2, where) as Vec2;
const rect = (v: unknown, where: string): Rect => {
  const r = nums(v, 4, where) as Rect;
  if (r[2] <= 0 || r[3] <= 0) fail(where, 'must have a positive size');
  return r;
};

function parseJiggle(v: unknown, where: string): Jiggle {
  const j = obj(v, where);
  return {
    stiffness: num(j.stiffness, `${where}.stiffness`, 1, 5000),
    // the springs are integrated in fixed 1/240 s sub-steps (semi-implicit Euler), which stays
    // stable while damping * step < 2: 300 keeps a safe margin (1.25)
    damping: num(j.damping, `${where}.damping`, 0, MAX_DAMPING),
    limit: num(j.limit, `${where}.limit`, 0, Math.PI),
    gravity: num(j.gravity ?? 0, `${where}.gravity`, -5000, 5000),
  };
}

function parseRule(v: unknown, where: string, bone: (n: unknown, w: string) => string): WeightRule {
  const r = obj(v, where);
  const names = (x: unknown, w: string): string[] => arr(x, w).map((b, i) => bone(b, `${w}[${i}]`));
  switch (r.kind) {
    case 'rigid':
      return { kind: 'rigid', bone: bone(r.bone, `${where}.bone`) };
    case 'chain': {
      const points = arr(r.points, `${where}.points`).map((p, i) => vec2(p, `${where}.points[${i}]`));
      if (points.length < 2) fail(`${where}.points`, 'needs at least two points');
      const bones = names(r.bones, `${where}.bones`);
      if (bones.length === 0) fail(`${where}.bones`, 'needs at least one bone');
      return {
        kind: 'chain',
        points,
        bones,
        base: bone(r.base, `${where}.base`),
        baseLen: num(r.baseLen, `${where}.baseLen`, 0.001, 1),
      };
    }
    case 'ear': {
      const bones = names(r.bones, `${where}.bones`);
      if (bones.length !== 2) fail(`${where}.bones`, 'must name two bones (base and tip)');
      return {
        kind: 'ear',
        base: vec2(r.base, `${where}.base`),
        tip: vec2(r.tip, `${where}.tip`),
        parent: bone(r.parent, `${where}.parent`),
        bones: [bones[0], bones[1]],
      };
    }
    case 'spine': {
      const bones = names(r.bones, `${where}.bones`);
      const ys = nums(r.ys, bones.length, `${where}.ys`);
      for (let i = 1; i < ys.length; i++) if (ys[i] <= ys[i - 1]) fail(`${where}.ys`, 'must increase');
      const legs = arr(r.legs ?? [], `${where}.legs`).map((l, i) => {
        const w = `${where}.legs[${i}]`;
        const o = obj(l, w);
        return {
          bone: bone(o.bone, `${w}.bone`),
          x: num(o.x, `${w}.x`),
          halfWidth: vec2(o.halfWidth, `${w}.halfWidth`),
          y: vec2(o.y, `${w}.y`),
        };
      });
      return { kind: 'spine', bones, ys, legs };
    }
    case 'head': {
      const n = obj(r.neck, `${where}.neck`);
      const rule: WeightRule = {
        kind: 'head',
        bone: bone(r.bone, `${where}.bone`),
        neck: {
          bone: bone(n.bone, `${where}.neck.bone`),
          weight: num(n.weight, `${where}.neck.weight`, 0, 1),
          y: vec2(n.y, `${where}.neck.y`),
        },
      };
      if (r.cheeks !== undefined) {
        const c = obj(r.cheeks, `${where}.cheeks`);
        rule.cheeks = {
          left: bone(c.left, `${where}.cheeks.left`),
          right: bone(c.right, `${where}.cheeks.right`),
          centerX: num(c.centerX, `${where}.cheeks.centerX`),
          dx: vec2(c.dx, `${where}.cheeks.dx`),
          y: vec2(c.y, `${where}.cheeks.y`),
        };
      }
      return rule;
    }
    default:
      fail(`${where}.kind`, 'must be one of rigid, chain, ear, spine, head');
  }
}

/** Validate a parsed `relief.json`. Throws `ReliefDefinitionError` naming the offending field. */
export function parseReliefDefinition(raw: unknown, expectedId: string): ReliefDefinition {
  const root = obj(raw, 'relief.json');
  if (root.version !== 1) fail('version', 'must be 1');
  const id = str(root.id, 'id');
  if (id !== expectedId) fail('id', `is "${id}" but the variant is "${expectedId}"`);

  const bones: BoneDef[] = arr(root.bones, 'bones').map((b, i) => {
    const w = `bones[${i}]`;
    const o = obj(b, w);
    const def: BoneDef = {
      name: str(o.name, `${w}.name`),
      parent: o.parent === null || o.parent === undefined ? null : str(o.parent, `${w}.parent`),
      pivot: vec2(o.pivot, `${w}.pivot`),
      tip: vec2(o.tip, `${w}.tip`),
    };
    if (o.jiggle !== undefined) def.jiggle = parseJiggle(o.jiggle, `${w}.jiggle`);
    return def;
  });
  const boneNames = new Set(bones.map((b) => b.name));
  for (const req of REQUIRED_BONES) if (!boneNames.has(req)) fail('bones', `must include "${req}"`);
  const bone = (v: unknown, where: string): string => {
    const n = str(v, where);
    if (!boneNames.has(n)) fail(where, `names unknown bone "${n}"`);
    return n;
  };

  const parts: ReliefPart[] = arr(root.parts, 'parts').map((p, i) => {
    const w = `parts[${i}]`;
    const o = obj(p, w);
    const part: ReliefPart = {
      name: str(o.name, `${w}.name`),
      atlas: rect(o.atlas, `${w}.atlas`),
      rect: rect(o.rect, `${w}.rect`),
      relief: num(o.relief, `${w}.relief`, 0, 500),
      z: num(o.z, `${w}.z`, -500, 500),
      cell: num(o.cell ?? 4, `${w}.cell`, 2, 64),
      weights: parseRule(o.weights, `${w}.weights`, bone),
    };
    if (o.surface !== undefined) part.surface = str(o.surface, `${w}.surface`);
    if (part.atlas[2] !== part.rect[2] || part.atlas[3] !== part.rect[3])
      fail(w, 'atlas and rect must be the same size');
    return part;
  });
  const partNames = new Set(parts.map((p) => p.name));
  for (const p of parts)
    if (p.surface && !partNames.has(p.surface))
      fail(`parts.${p.name}.surface`, `unknown part "${p.surface}"`);

  const eyes: ReliefEye[] = arr(root.eyes, 'eyes').map((e, i) => {
    const w = `eyes[${i}]`;
    const o = obj(e, w);
    const ell = obj(o.ellipse, `${w}.ellipse`);
    const surface = str(o.surface ?? 'head', `${w}.surface`);
    if (!partNames.has(surface)) fail(`${w}.surface`, `unknown part "${surface}"`);
    return {
      name: str(o.name, `${w}.name`),
      atlas: rect(o.atlas, `${w}.atlas`),
      closedAtlas: rect(o.closedAtlas, `${w}.closedAtlas`),
      rect: rect(o.rect, `${w}.rect`),
      ellipse: { c: vec2(ell.c, `${w}.ellipse.c`), r: vec2(ell.r, `${w}.ellipse.r`) },
      bone: bone(o.bone ?? 'head', `${w}.bone`),
      surface,
    };
  });

  const order = arr(root.order, 'order').map((n, i) => str(n, `order[${i}]`));
  for (const n of order) if (n !== '#eyes' && !partNames.has(n)) fail('order', `names unknown part "${n}"`);
  for (const n of partNames) if (!order.includes(n)) fail('order', `is missing part "${n}"`);
  if (eyes.length > 0 && !order.includes('#eyes')) fail('order', 'must place "#eyes"');

  const roles = obj(root.roles, 'roles');
  const ears = obj(roles.ears, 'roles.ears');
  const wings = roles.wings === null || roles.wings === undefined ? null : obj(roles.wings, 'roles.wings');
  const neck = obj(root.neck, 'neck');
  const turn = obj(root.turn ?? {}, 'turn');
  const poses: Record<string, { scale: number }> = {};
  for (const [name, p] of Object.entries(obj(root.poses ?? {}, 'poses'))) {
    poses[str(name, `poses.${name}`)] = {
      scale: num(obj(p, `poses.${name}`).scale ?? 1, `poses.${name}.scale`, 0.3, 2),
    };
  }

  // Perspective divides by (focal - z): a focal length near the deepest relief point would blow a
  // part up to infinity, so it has to stay well clear of it.
  const focal = num(root.focal ?? 1500, 'focal', 100, 100000);
  const deepest = Math.max(0, ...parts.map((p) => Math.abs(p.z) + p.relief));
  if (focal <= 2 * deepest) fail('focal', `must be more than twice the deepest relief (${deepest}), got ${focal}`);

  return {
    version: 1,
    id,
    atlas: str(root.atlas, 'atlas', SAFE_FILE),
    depth: str(root.depth, 'depth', SAFE_FILE),
    artSize: num(root.artSize, 'artSize', 16, 8192),
    ground: vec2(root.ground, 'ground'),
    artHeight: num(root.artHeight, 'artHeight', 1, 8192),
    bones,
    parts,
    eyes,
    order,
    headBones: arr(root.headBones, 'headBones').map((b, i) => bone(b, `headBones[${i}]`)),
    neck: { bone: bone(neck.bone, 'neck.bone'), headness: num(neck.headness, 'neck.headness', 0, 1) },
    headCenter: nums(root.headCenter, 3, 'headCenter') as [number, number, number],
    bodyCenter: nums(root.bodyCenter, 3, 'bodyCenter') as [number, number, number],
    lookAnchor: vec2(root.lookAnchor, 'lookAnchor'),
    light: nums(root.light, 3, 'light') as [number, number, number],
    focal,
    turn: {
      yaw: num(turn.yaw ?? 0.42, 'turn.yaw', 0, 1),
      pitch: num(turn.pitch ?? 0.28, 'turn.pitch', 0, 1),
      body: num(turn.body ?? 0.32, 'turn.body', 0, 1),
    },
    roles: {
      ears: {
        left: arr(ears.left, 'roles.ears.left').map((b, i) => bone(b, `roles.ears.left[${i}]`)),
        right: arr(ears.right, 'roles.ears.right').map((b, i) => bone(b, `roles.ears.right[${i}]`)),
      },
      wings: wings
        ? { left: bone(wings.left, 'roles.wings.left'), right: bone(wings.right, 'roles.wings.right') }
        : null,
      tails: arr(roles.tails ?? [], 'roles.tails').map((t, i) =>
        arr(t, `roles.tails[${i}]`).map((b, k) => bone(b, `roles.tails[${i}][${k}]`)),
      ),
      legs: arr(roles.legs ?? [], 'roles.legs').map((b, i) => bone(b, `roles.legs[${i}]`)),
    },
    poses,
  };
}

export interface LoadedRelief {
  definition: ReliefDefinition;
  atlas: TexImageSource;
  depth: TexImageSource;
}

export interface ReliefLoadOptions {
  /** Directory the variant is served from, ending in a slash. */
  variantBase: string;
  /** Sub-directory of the relief assets, from the variant's `rig.json`. */
  dir: string;
  fetchJson: (url: string) => Promise<unknown>;
  loadImage: (url: string) => Promise<TexImageSource>;
}

/** Fetch, validate and preload a relief rig. Throws on anything unusable. */
export async function loadRelief(expectedId: string, options: ReliefLoadOptions): Promise<LoadedRelief> {
  const dir = str(options.dir, 'rig.json relief.dir', SAFE_FILE);
  const base = `${options.variantBase}${dir}/`;
  const raw = await options.fetchJson(`${base}relief.json`);
  if (raw === null) throw new ReliefDefinitionError('relief.json not found');
  const definition = parseReliefDefinition(raw, expectedId);
  const [atlas, depth] = await Promise.all([
    options.loadImage(`${base}${definition.atlas}`),
    options.loadImage(`${base}${definition.depth}`),
  ]);
  return { definition, atlas, depth };
}
